import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type NumberCounterProps = Record<string, any>;

const NumberCounter: React.FC<NumberCounterProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  targetValue = 700000,
  prefix = "",
  suffix = "$",
  textColor = "#ffffff",
  labelText = "TOTAL EARNINGS",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Space Grotesk"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  const s = Math.min(width, height);

  // Animation Timing Constants
  const entranceDuration = Math.floor(fps * 0.8);
  const counterDuration = Math.floor(fps * durationInSeconds * 0.7);

  // Animations
  const containerOpacity = interpolate(
    frame,
    [0, entranceDuration],
    [0, 1],
    {
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }
  );

  const containerScale = spring({
    frame,
    fps,
    config: {
      damping: 14,
      mass: 0.8,
    },
  });

  const labelOpacity = interpolate(
    frame,
    [entranceDuration * 0.5, entranceDuration * 1.5],
    [0, 0.7],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    }
  );

  const labelY = spring({
    frame: frame - Math.floor(entranceDuration * 0.5),
    fps,
    config: {
      damping: 12,
    },
  });

  const currentNumber = interpolate(
    frame,
    [entranceDuration, entranceDuration + counterDuration],
    [0, targetValue],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.exp),
    }
  );

  // Format the number with spaces as requested (e.g. 700 000 instead of 700,000)
  const formattedValue = Math.floor(currentNumber)
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, " ");

  // Responsive Typography
  const mainFontSize = s * 0.2;
  const labelFontSize = s * 0.035;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Space Grotesk",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          opacity: containerOpacity,
          transform: `scale(${containerScale})`,
          transition: "none",
        }}
      >
        {/* Label */}
        {labelText && (
          <div
            style={{
              fontSize: labelFontSize,
              color: textColor,
              opacity: labelOpacity,
              fontWeight: 600,
              letterSpacing: s * 0.01,
              textTransform: "uppercase",
              transform: `translateY(${interpolate(labelY, [0, 1], [20, 0])}px)`,
              marginBottom: s * 0.02,
              transition: "none",
            }}
          >
            {labelText}
          </div>
        )}

        {/* Counter */}
        <div
          style={{
            fontSize: mainFontSize,
            color: textColor,
            fontWeight: 700,
            lineHeight: 1,
            letterSpacing: -s * 0.005,
            fontVariantNumeric: "tabular-nums",
            display: "flex",
            alignItems: "baseline",
            transition: "none",
          }}
        >
          {prefix && (
            <span
              style={{
                fontSize: mainFontSize * 0.6,
                marginRight: s * 0.01,
                opacity: 0.8,
              }}
            >
              {prefix}
            </span>
          )}
          <span>{formattedValue}</span>
          {suffix && (
            <span
              style={{
                fontSize: mainFontSize * 0.6,
                marginLeft: s * 0.02,
                opacity: 0.8,
              }}
            >
              {suffix}
            </span>
          )}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default NumberCounter;